import{loadSpriteAtlas}from './sanguo-cast.mjs';
import{lordDirection}from './sanguo-motion.mjs';
export class SanguoPlayer{
 static async create(container,scene){const p=new SanguoPlayer();p.scene=scene;p.isSanguo=true;p.frames=await loadSpriteAtlas('assets/scene/skins/sanguo/lord-v4.png',4,2);p.maxHeight=Math.max(...p.frames.map(f=>f.canvas.height));p.animationState={timeScale:1.5,data:{defaultMix:.2},tracks:[{trackTime:0,animation:{name:'idle_f'}}]};p.skeleton={data:{findAnimation:name=>({duration:scene.pieceProfile.animations[name]?.duration||1.5})}};p.canvas=document.createElement('canvas');p.canvas.width=300;p.canvas.height=340;p.canvas.style.cssText='display:block;width:100%;height:100%';container.replaceChildren(p.canvas);p.ctx=p.canvas.getContext('2d');p.resize(scene.zoom);p.setDirection(scene.direction(scene.position));p.setAnimation('idle_'+(scene.direction(scene.position).back?'b':'f'),true);p.tick(performance.now());return p;}
 resize(zoom){this.scale=5.5/zoom;const el=this.scene.pieceElement||document.querySelector('#piece');el.style.width=150*this.scale+'px';el.style.height=170*this.scale+'px';el.style.transform='translate(-50%,-100%)';document.querySelector('#spine').style.transform='none';}
 setDirection(d){this.direction={...d,flip:d.back?!d.flip:d.flip};this.travelDirection=false;this.retarget();}
 setTravel(from,to){this.direction=lordDirection(from,to,this.direction);this.travelDirection=true;this.retarget();return this.direction;}
 retarget(){if(!this.name)return;this.name=this.name.replace(/_[fb]$/,'_'+(this.direction.back?'b':'f'));if(this.animationState?.tracks[0])this.animationState.tracks[0].animation.name=this.name;this.render();}
 setAnimation(name,loop=true){this.name=name;this.loop=loop;this.animationState.tracks[0]={trackTime:0,animation:{name,duration:this.skeleton.data.findAnimation(name).duration}};this.render();}
 tick(now){const dt=Math.min(.1,(now-(this.lastTime??now))/1000);this.lastTime=now;this.animationState.tracks[0].trackTime+=dt*this.animationState.timeScale;this.render();this.raf=requestAnimationFrame(t=>this.tick(t));}
 render(){const c=this.ctx;if(!c)return;const t=this.animationState.tracks[0].trackTime,back=this.name.endsWith('_b'),walk=/walk|run/.test(this.name),index=(back?4:0)+(walk?Math.floor(t*7)%4:0),frame=this.frames[index].canvas;this.frameIndex=index;const h=238*frame.height/this.maxHeight,w=h*frame.width/frame.height;let lift=0,stretch=1;if(this.name.includes('jump')){const duration=this.skeleton.data.findAnimation(this.name).duration,u=Math.min(1,t/duration);lift=Math.sin(Math.PI*u)*48;stretch=1+.04*Math.sin(2*Math.PI*u);}else if(!walk)stretch=1+Math.sin(t*2.2)*.008;c.clearRect(0,0,300,340);c.save();c.translate(150,340-lift);if(this.direction?.flip)c.scale(-1,1);c.scale(1,stretch);c.drawImage(frame,-w/2,-h,w,h);c.restore();}
 dispose(){cancelAnimationFrame(this.raf);}
}
